func maxInt(a int, b int) int {
	if a > b {
		return a
	}
	return b
}

func minInt(a int, b int) int {
	if a < b {
		return a
	}
	return b
}

func absInt(a int) int {
	if a < 0 {
		return -a
	}
	return a
}

func getScanner(file string) *bufio.Scanner {
	var scanner *bufio.Scanner
	if LOCAL_TEST {
		fp, err := os.Open(file)
		if err != nil {
			panic("Error: Can not open file ")
		}
		if !REPEAT {
			fmt.Fprintf(os.Stderr, "---CASE %s---\n", file)
		}
		scanner = bufio.NewScanner(fp)
	} else {
		scanner = bufio.NewScanner(os.Stdin)
	}
	scanner.Buffer(make([]byte, 1000000), 1000000)
	return scanner
}

func getInputs(gConst *GameConst) {
	// 例
	gConst.Scanner.Scan()
	splitedInput := strings.Split(gConst.Scanner.Text(), " ")
	// N, _ := strconv.Atoi(splitedInput[0])
	M, _ := strconv.Atoi(splitedInput[1])
	// H :=
	T, _ := strconv.Atoi(splitedInput[3])
	D, _ := strconv.Atoi(splitedInput[4])
	gConst.NumTubes = M
	gConst.MaxTurn = T
	gConst.TubeCost = D

	gConst.TubeCMYs = make([][3]float64, gConst.NumTubes)
	// チューブの色取得
	for i := 0; i < gConst.NumTubes; i++ {
		gConst.Scanner.Scan()
		splitedInput = strings.Split(gConst.Scanner.Text(), " ")
		for j := 0; j < 3; j++ {
			c, _ := strconv.ParseFloat(splitedInput[j], 64)
			gConst.TubeCMYs[i][j] = c
		}
	}
	// 目的の色を取得
	for i := 0; i < NUM_REQUESTED; i++ {
		gConst.Scanner.Scan()
		splitedInput = strings.Split(gConst.Scanner.Text(), " ")
		for j := 0; j < 3; j++ {
			c, _ := strconv.ParseFloat(splitedInput[j], 64)
			gConst.RequestedCMYs[i][j] = c
		}
	}
	basePoints := make([]Vec3, 0)
	subPoints := make([]Vec3, 0, NUM_REQUESTED)
	for _, cmy := range gConst.TubeCMYs {
		vec := Vec3{cmy[0], cmy[1], cmy[2]}
		basePoints = append(basePoints, vec)
	}
	for _, cmy := range gConst.RequestedCMYs {
		vec := Vec3{cmy[0], cmy[1], cmy[2]}
		subPoints = append(subPoints, vec)
	}
	minimalbase := MinimalSupportIndices(basePoints, subPoints, 1e-9)
	maxNum := 0
	if gConst.MaxTurn < 17000 {
		maxNum = 10
	} else if gConst.MaxTurn < 18000 {
		maxNum = 9
	} else if gConst.MaxTurn < 20000 {
		maxNum = 8
	} else {
		maxNum = 7
	}
	minimalbase = augmentIndicesWithClusters(gConst.TubeCMYs, minimalbase, gConst.RequestedCMYs[:], maxNum)
	// if M == 4 {
	// 	minimalbase = append(minimalbase, minimalbase...)
	// }
	gConst.BaseTubes = minimalbase
	gConst.NumBaseTubes = len(minimalbase)
	gConst.CellPerGroup = BOARD_WIDTH * (BOARD_WIDTH - 1) / gConst.NumBaseTubes
	gConst.useAll = false
	if gConst.MaxTurn > 20000 {
		gConst.useAll = gConst.TubeCost > 1000
	} else if gConst.MaxTurn > 17000 {
		gConst.useAll = gConst.TubeCost > 200
	} else {
		gConst.useAll = true
	}
}

