type Solver struct {
	timeLimit int // solverに与えられた時間制限 microsecond
}

func NewSolver(timeLimit int) *Solver {
	s := Solver{}
	s.timeLimit = timeLimit
	return &s
}

func (s *Solver) Solve(gameConst *GameConst) ([]*Action, int) {
	start := time.Now()
	_ = start
	maxActions := make([]*Action, 0, gameConst.MaxTurn)
	maxScore := 0.0
	_ = maxScore

	// 貪欲を書くならここ
	palette := NewPalette(gameConst)
	palette.Init()

	// 順番に処理
	for {
		if palette.progress == NUM_REQUESTED {
			break
		}
		var bestRecipe *Recipe
		if gameConst.useAll {
			if palette.progress >= NUM_REQUESTED-40 {
				break
			}
		} else {
			if palette.progress >= NUM_REQUESTED-20 {
				if 10*(NUM_REQUESTED-palette.progress) < gameConst.TubeCost {
					// 余りなく処理するため、次フェーズへ
					break
				}
				if palette.progress == NUM_REQUESTED-10 {
					break
				}
			}
		}
		bestRecipe = bruteforce(palette, gameConst.RequestedCMYs[palette.progress], gameConst)
		as := proceed(bestRecipe, palette, gameConst, false)
		maxActions = append(maxActions, as...)
	}
	// fmt.Fprintln(os.Stderr, palette.sumError)
	bestScore := float64(INF)
	bestDiscard := 0.0
	bestPenalty := 0
	maxActions2 := make([]*Action, 0)
	for l := 0; l < 100; l++ {
		if time.Since(start).Microseconds() > TIME_LIMIT {
			// 危ないのでbreak
			break
		}
		reservations := make([][4]int, 0)
		paramreservations := make([][4]float64, 0)
		estimateCap := make([]int, gameConst.NumBaseTubes)
		cPalette := palette.Copy(gameConst)
		actions2 := make([]*Action, 0)
		addCount := make([]int, gameConst.NumBaseTubes)
		remainedNeededAmounts := make([]float64, gameConst.NumBaseTubes)
		for {
			if cPalette.progress == NUM_REQUESTED {
				break
			}
			if len(reservations) == 0 {
				reservations, paramreservations, estimateCap = makePlan(cPalette, gameConst)
				for i := range reservations {
					for j := range reservations[i] {
						kind := reservations[i][j]
						param := paramreservations[i][j]
						remainedNeededAmounts[kind] += param
					}
				}
			}
			var bestRecipe *Recipe
			if gameConst.useAll {
				if cPalette.progress == NUM_REQUESTED-1 {
					bestRecipe = NewRecipe(gameConst.NumBaseTubes)
					for i := range bestRecipe.recipe {
						bestRecipe.recipe[i][0] = 0
						bestRecipe.recipe[i][1] = cPalette.sub[i].size
						bestRecipe.recipe[i][2] = 0
						bestRecipe.add[i] = 0
					}
				} else {
					v := 0.0
					c1:=gameConst.TubeCMYs[gameConst.BaseTubes[reservations[0][0]]]
					c2:=gameConst.TubeCMYs[gameConst.BaseTubes[reservations[0][1]]]
					c3:=gameConst.TubeCMYs[gameConst.BaseTubes[reservations[0][2]]]
					c4:=gameConst.TubeCMYs[gameConst.BaseTubes[reservations[0][3]]]
					estimatedSize := float64(cPalette.main.size)
					mainparam := SolveWeights(c1, c2, c3, c4, cPalette.main.CMY)
					param := paramreservations[0]
					for i := range param {
						param[i] = param[i]*(1+cPalette.main.amount*estimatedSize/float64(cPalette.main.size)) - mainparam[i]*cPalette.main.amount*estimatedSize/float64(cPalette.main.size)
					}
					nparam, _ := adjustWeights(param, true)


					v, bestRecipe = bruteforceMode(cPalette, reservations[0], nparam, gameConst, 16, -1, 0, 1, estimateCap, addCount, paramreservations, reservations, remainedNeededAmounts)
					_ = v
					// fmt.Fprintln(os.Stderr, "DEBUG:", "bestValue", v,bestRecipe)
				}
			} else {
				_, bestRecipe = bruteforceMode(cPalette, reservations[0], paramreservations[0], gameConst, 16, -1, 0, 1, nil, nil, nil, nil, nil)
			}
			for i := range bestRecipe.add {
				if bestRecipe.add[i] == 1 {
					addCount[i]++
				}
			}
			for i := range paramreservations[0] {
				kind := reservations[0][i]
				remainedNeededAmounts[kind] -= paramreservations[0][i]
			}
			as := proceed(bestRecipe, cPalette, gameConst, true)
			actions2 = append(actions2, as...)

			reservations = reservations[1:]
			paramreservations = paramreservations[1:]
		}
		sc := cPalette.CalcScore(gameConst)
		if len(maxActions)+len(actions2) > gameConst.MaxTurn {
			continue
		}
		// fmt.Fprintln(os.Stderr, l, sc)
		if sc < bestScore {
			bestScore = sc
			bestDiscard = cPalette.sumDiscard
			bestPenalty = cPalette.sumProc1 - NUM_REQUESTED
			maxActions2 = actions2
		}
	}
	maxActions = append(maxActions, maxActions2...)

	// fmt.Fprintln(os.Stderr, palette.sumProc1-NUM_REQUESTED, gameConst.NumBaseTubes)
	fmt.Fprintln(os.Stderr, "score:", bestScore, "basetube:", gameConst.NumBaseTubes, bestPenalty, bestDiscard)
	score := int(bestScore)
	// 貪欲ここまで
	if len(maxActions) > gameConst.MaxTurn {
		score = -1
	}
	if len(maxActions2) == 0 {
		// 見つからなかった
		score = -1
	}
	fmt.Fprintln(os.Stderr, len(maxActions), gameConst.MaxTurn)

	return maxActions, score
}

func getAmountFromRecipe(willAmount float64, willSize int, add int, recipeForWill [4]int) float64 {
	if recipeForWill[1] == 0 {
		return 0
	}
	scheduledAmount := (willAmount + float64(add))                                      // 基本量
	scheduledAmount *= 1 - float64(recipeForWill[2])/float64(willSize+recipeForWill[0]) // keep除外
	scheduledAmount *= float64(recipeForWill[1]) / float64(willSize+recipeForWill[0]-recipeForWill[2])
	return scheduledAmount
}

func proceed(bestRecipe *Recipe, palette *Palette, gameConst *GameConst, usepanic bool) []*Action {
	maxActions := []*Action{}
	// actionに追加
	// keepなしの場合のexpand
	for subIndex := range bestRecipe.recipe {
		if bestRecipe.recipe[subIndex][2] == 0 && bestRecipe.recipe[subIndex][0] != 0 {
			oldsize := palette.sub[subIndex].size
			newsize := palette.sub[subIndex].size + bestRecipe.recipe[subIndex][0]
			if newsize != 0 {
				action := NewAction()
				action.actionType = 4
				action.pos = coords[gameConst.NumBaseTubes][subIndex][newsize]
				action.pos2 = coords[gameConst.NumBaseTubes][subIndex][newsize-1]
				maxActions = append(maxActions, action)
				palette.turn++
			}
			if oldsize != 0 {
				action := NewAction()
				action.actionType = 4
				action.pos = coords[gameConst.NumBaseTubes][subIndex][oldsize]
				action.pos2 = coords[gameConst.NumBaseTubes][subIndex][oldsize-1]
				maxActions = append(maxActions, action)
				palette.turn++
			}
		}
	}
	for i := range bestRecipe.add {
		if bestRecipe.add[i] > 0 {
			action := NewAction()
			action.actionType = 1
			action.pos = coords[gameConst.NumBaseTubes][i][0]
			action.tube = gameConst.BaseTubes[i]
			maxActions = append(maxActions, action)
			palette.turn++
		}
	}
	// keep
	for subIndex := range bestRecipe.recipe {
		if bestRecipe.recipe[subIndex][2] != 0 {
			newsize := bestRecipe.recipe[subIndex][2]
			if newsize != 0 {
				action := NewAction()
				action.actionType = 4
				action.pos = coords[gameConst.NumBaseTubes][subIndex][newsize]
				action.pos2 = coords[gameConst.NumBaseTubes][subIndex][newsize-1]
				maxActions = append(maxActions, action)
				palette.turn++
			}
		}
	}
	// keepありの場合のexpand
	for subIndex := range bestRecipe.recipe {
		if bestRecipe.recipe[subIndex][2] != 0 && bestRecipe.recipe[subIndex][0] != 0 {
			oldsize := palette.sub[subIndex].size
			newsize := palette.sub[subIndex].size + bestRecipe.recipe[subIndex][0]
			if newsize != bestRecipe.recipe[subIndex][2] {
				action := NewAction()
				action.actionType = 4
				action.pos = coords[gameConst.NumBaseTubes][subIndex][newsize]
				action.pos2 = coords[gameConst.NumBaseTubes][subIndex][newsize-1]
				maxActions = append(maxActions, action)
				palette.turn++
			}
			if oldsize != bestRecipe.recipe[subIndex][2] {
				action := NewAction()
				action.actionType = 4
				action.pos = coords[gameConst.NumBaseTubes][subIndex][oldsize]
				action.pos2 = coords[gameConst.NumBaseTubes][subIndex][oldsize-1]
				maxActions = append(maxActions, action)
				palette.turn++
			}
		}
	}
	for subIndex := range bestRecipe.recipe {
		if bestRecipe.recipe[subIndex][1] != 0 {
			oldsize := palette.sub[subIndex].size + bestRecipe.recipe[subIndex][0]
			newsize := palette.sub[subIndex].size + bestRecipe.recipe[subIndex][0] - bestRecipe.recipe[subIndex][1]
			if newsize != bestRecipe.recipe[subIndex][2] {
				action := NewAction()
				action.actionType = 4
				action.pos = coords[gameConst.NumBaseTubes][subIndex][newsize]
				action.pos2 = coords[gameConst.NumBaseTubes][subIndex][newsize-1]
				maxActions = append(maxActions, action)
				palette.turn++
			}
			if oldsize != bestRecipe.recipe[subIndex][2] {
				action := NewAction()
				action.actionType = 4
				action.pos = coords[gameConst.NumBaseTubes][subIndex][oldsize]
				action.pos2 = coords[gameConst.NumBaseTubes][subIndex][oldsize-1]
				maxActions = append(maxActions, action)
				palette.turn++
			}
		}
	}

	palette.Blend(gameConst, bestRecipe)
	// releasekeep
	for subIndex := range bestRecipe.recipe {
		if bestRecipe.recipe[subIndex][2] != 0 {
			newsize := bestRecipe.recipe[subIndex][2]
			if newsize != 0 && newsize != palette.sub[subIndex].size {
				action := NewAction()
				action.actionType = 4
				action.pos = coords[gameConst.NumBaseTubes][subIndex][newsize]
				action.pos2 = coords[gameConst.NumBaseTubes][subIndex][newsize-1]
				maxActions = append(maxActions, action)
				palette.turn++
			}
		}
	}

	if true {
		action := NewAction()
		action.actionType = 2
		action.pos = [2]int{0, 0}
		maxActions = append(maxActions, action)
		palette.turn++
	}
	// fmt.Fprintln(os.Stderr, bestRecipe.recipe)
	palette.Deliver(gameConst, true)
	// if palette.progress < NUM_REQUESTED && palette.main.amount*calcDiff(gameConst.RequestedCMYs[palette.progress-1], gameConst.RequestedCMYs[palette.progress]) > 0.0001 {
	if palette.progress < NUM_REQUESTED && !gameConst.useAll {
		action := NewAction()
		action.actionType = 3
		action.pos = [2]int{0, 0}
		maxActions = append(maxActions, action)
		palette.turn++
		palette.ClearMain(gameConst)
	}
	return maxActions
}

func makePlan(palette *Palette, gameConst *GameConst) ([][4]int, [][4]float64, []int) {
	// BaseTubeから4色を選ぶ方法は高々8C4=70通り
	candidates := [][][4]int{}
	paramcandidates := [][][4]float64{}
	for index := 0; index+palette.progress < NUM_REQUESTED; index++ {
		cands := [][4]int{}
		paramcands := [][4]float64{}
		goal := gameConst.RequestedCMYs[index+palette.progress]
		for i := 0; i < gameConst.NumBaseTubes; i++ {
			c1 := gameConst.TubeCMYs[gameConst.BaseTubes[i]]
			for j := i + 1; j < gameConst.NumBaseTubes; j++ {
				c2 := gameConst.TubeCMYs[gameConst.BaseTubes[j]]
				for k := j + 1; k < gameConst.NumBaseTubes; k++ {
					c3 := gameConst.TubeCMYs[gameConst.BaseTubes[k]]
					for l := k + 1; l < gameConst.NumBaseTubes; l++ {
						c4 := gameConst.TubeCMYs[gameConst.BaseTubes[l]]
						param := SolveWeights(c1, c2, c3, c4, goal)
						param, ok := adjustWeights(param, false)
						if ok {
							// 可能な選択肢なので追加
							kinds := [4]int{i, j, k, l}
							cands = append(cands, kinds)
							paramcands = append(paramcands, param)
						}
					}
				}
			}
		}
		candidates = append(candidates, cands)
		paramcandidates = append(paramcandidates, paramcands)
	}
	initialVolumes := make([]float64, gameConst.NumBaseTubes)
	for i := range initialVolumes {
		initialVolumes[i] = 1 - palette.sub[i].amount + 0.01
	}
	initialTemp := 2.0
	finalTemp := 0.01
	bestselect := GPTSimulatedAnnealing(candidates, paramcandidates, gameConst.NumBaseTubes, gameConst, initialVolumes, initialTemp, finalTemp, gameConst.useAll)
	reservation := [][4]int{}
	paramreservation := [][4]float64{}
	for i := range bestselect {
		reservation = append(reservation, candidates[i][bestselect[i]])
		paramreservation = append(paramreservation, paramcandidates[i][bestselect[i]])
	}
	sumParam := make([]float64, gameConst.NumBaseTubes)
	for i := range reservation {
		for j := range reservation[i] {
			kind := reservation[i][j]
			param := paramreservation[i][j]
			sumParam[kind] += param
		}
	}
	estimatedCap := make([]int, gameConst.NumBaseTubes)
	for i := 0; i < NUM_REQUESTED-palette.sumProc1; i++ {
		// 最も不足する色を足す
		minValue := float64(INF)
		minIndex := -1
		for j := range sumParam {
			v := float64(estimatedCap[j]) + palette.sub[j].amount - sumParam[j]
			if v < minValue {
				minValue = v
				minIndex = j
			}
		}
		estimatedCap[minIndex]++
	}
	return reservation, paramreservation, estimatedCap
}

// GPTSimulatedAnnealing performs a simulated annealing optimization to choose one candidate
// per turn (0..len(candidates)-1) to minimize the total cost defined as the sum over k pools
// of ceil(volume), where volume starts from initialVolumes and accumulates according to paramcandidates.
// The annealing schedule runs for a fixed time (100ms) and interpolates temperature linearly
// from initialTemp down to finalTemp over that period.
// Inputs:
//   - candidates: a slice of length T (here T=30) where each element is a slice of [4]int.
//     candidates[t][i] = [p0, p1, p2, p3] are the pool-indices affected if you pick option i at turn t.
//   - paramcandidates: a slice of length T where each element is a slice of [4]float64.
//     paramcandidates[t][i] = [a0, a1, a2, a3] are the amounts to add to those pools when picking option i.
//     For each i, a0+a1+a2+a3 ≈ 1.0.
//   - k: the number of pools (indices run 0..k-1).
//   - initialVolumes: a slice of length k giving the starting volume in each pool.
//   - initialTemp: starting temperature for annealing.
//   - finalTemp: final temperature at the end of the time window.
//
// Output:
//   - bestSolution: a slice of length T, where bestSolution[t] = chosen index i into candidates[t].
func GPTSimulatedAnnealing(
	candidates [][][4]int,
	paramcandidates [][][4]float64,
	k int,
	gameConst *GameConst,
	initialVolumes []float64,
	initialTemp, finalTemp float64,
	useAll bool,
) []int {

	T := len(candidates)

	// Check that initialVolumes has length k
	if len(initialVolumes) != k {
		panic("initialVolumes length must equal k")
	}
	// initialTemp should be > finalTemp >= 0
	if initialTemp <= finalTemp {
		panic("initialTemp must be greater than finalTemp")
	}

	// Initialize a random starting solution: pick one random candidate per turn
	currentSolution := make([]int, T)
	for t := 0; t < T; t++ {
		nOptions := len(candidates[t])
		currentSolution[t] = gameConst.Random.Intn(nOptions)
	}

	// currentVolumes[p] = total accumulated volume in pool p, starting from initialVolumes
	currentVolumes := make([]float64, k)
	copy(currentVolumes, initialVolumes)

	plus := 0.000
	// Build initial volumes from currentSolution
	for t := 0; t < T; t++ {
		choice := currentSolution[t]
		for j := 0; j < 4; j++ {
			p := candidates[t][choice][j]
			a := paramcandidates[t][choice][j]
			currentVolumes[p] += (a + plus)
		}
	}

	// Compute initial cost = sum over p of ceil(currentVolumes[p])
	currentCost := 0.0
	if useAll {
		for p := 0; p < k; p++ {
			currentCost += math.Abs(currentVolumes[p] - math.Max(math.Round(currentVolumes[p]), 1))
		}
	} else {
		for p := 0; p < k; p++ {
			currentCost += math.Ceil(currentVolumes[p])
		}
	}

	// Keep track of the best solution seen so far
	bestSolution := make([]int, T)
	copy(bestSolution, currentSolution)
	bestCost := currentCost

	// Helper: if slice does not already contain v, append it
	uniqueAppend := func(slice []int, v int) []int {
		for _, x := range slice {
			if x == v {
				return slice
			}
		}
		return append(slice, v)
	}

	startTime := time.Now()
	timeLimit := 20 * time.Millisecond
	iter := 0
	elapsed := time.Since(startTime)
	fraction := 0.0
	temp := 0.0
	numaccepted:=0
	for {
		if iter&(0b111111111) == 0 {
			elapsed = time.Since(startTime)
			if elapsed >= timeLimit {
				break
			}
			fraction = float64(elapsed) / float64(timeLimit) // in [0,1)
			// Compute current temperature by linear interpolation
			temp = initialTemp*math.Pow((1-fraction),2.5) + finalTemp*(1-math.Pow((1-fraction),2.5))
			// fmt.Fprintln(os.Stderr, iter,numaccepted, temp, bestCost, currentCost)
		}
		iter++

		// Pick a random turn to change
		t := gameConst.Random.Intn(T)
		oldChoice := currentSolution[t]
		nOptions := len(candidates[t])
		if nOptions <= 1 {
			// no alternative at this turn
			continue
		}
		// Pick a new candidate index different from oldChoice
		newChoice := gameConst.Random.Intn(nOptions)
		for newChoice == oldChoice {
			newChoice = gameConst.Random.Intn(nOptions)
		}

		// Gather the set of pools whose volumes will change
		var affectedPools []int
		for j := 0; j < 4; j++ {
			pOld := candidates[t][oldChoice][j]
			affectedPools = uniqueAppend(affectedPools, pOld)
			pNew := candidates[t][newChoice][j]
			affectedPools = uniqueAppend(affectedPools, pNew)
		}

		// Compute the cost delta for changing from oldChoice to newChoice at turn t
		deltaCost := 0.0
		for _, p := range affectedPools {
			// Sum of amounts currently contributed by oldChoice for this pool p
			sumOld := 0.0
			for j := 0; j < 4; j++ {
				if candidates[t][oldChoice][j] == p {
					sumOld += (paramcandidates[t][oldChoice][j] + plus)
				}
			}
			// Sum of amounts that would be contributed by newChoice for this pool p
			sumNew := 0.0
			for j := 0; j < 4; j++ {
				if candidates[t][newChoice][j] == p {
					sumNew += (paramcandidates[t][newChoice][j] + plus)
				}
			}
			vOld := currentVolumes[p]
			vNew := vOld - sumOld + sumNew
			// cost change for pool p
			if useAll {
				oldC := math.Abs(vOld - math.Max(math.Round(vOld), 1))
				newC := math.Abs(vNew - math.Max(math.Round(vNew), 1))
				deltaCost += newC - oldC
			} else {
				deltaCost += math.Ceil(vNew) - math.Ceil(vOld)
			}
		}

		// Decide whether to accept the move
		accept := false
		if deltaCost < 0 {
			accept = true
		} else {
			// If temperature is extremely low (approaching zero), avoid dividing by zero
			if temp > 1e-12 {
				if gameConst.Random.Float64() < math.Exp(-deltaCost/temp) {
					accept = true
				}
			}
		}

		if accept {
			numaccepted++
			// Update solution
			currentSolution[t] = newChoice
			// Update volumes and currentCost
			for _, p := range affectedPools {
				// Subtract old amounts, add new amounts
				sumOld := 0.0
				for j := 0; j < 4; j++ {
					if candidates[t][oldChoice][j] == p {
						sumOld += (paramcandidates[t][oldChoice][j] + plus)
					}
				}
				sumNew := 0.0
				for j := 0; j < 4; j++ {
					if candidates[t][newChoice][j] == p {
						sumNew += (paramcandidates[t][newChoice][j] + plus)
					}
				}
				currentVolumes[p] = currentVolumes[p] - sumOld + sumNew
			}
			currentCost += deltaCost

			// Track best
			if currentCost < bestCost {
				bestCost = currentCost
				copy(bestSolution, currentSolution)
			}
		}
	}
	// s := 0.0
	// for i := range currentVolumes {
	// 	s += currentVolumes[i]
	// }
	// fmt.Fprintln(os.Stderr, s, bestCost)
	// fmt.Fprintln(os.Stderr, "iter:", iter)
	return bestSolution
}

func adjustWeights(param [4]float64, resize bool) ([4]float64, bool) {
	ok := true
	for m := range param {
		if param[m] < -WEAK_EPSILON {
			param[m] = 0
			ok = false
		}
		if param[m] > 1+WEAK_EPSILON {
			if !resize {
				param[m] = 1
			}
			ok = false
		}
		if !resize {
			if param[m] > 1 {
				param[m] = 1
			}
		}
		if param[m] < 0 {
			param[m] = 0
		}
	}
	sump := 0.0
	for i := range param {
		sump += param[i]
	}
	if resize {
		newp := [4]float64{}
		for i := range newp {
			newp[i] = param[i] / sump
		}
		return newp, true
	}
	return param, ok
}

func (runner *Runner) doGame(file string) Result {
	result := Result{}
	scanner := getScanner(FILE + "\\" + file + ".txt")

	// 初期値設定処理

	gameConst := NewGameConst(runner)
	gameConst.SetScanner(scanner)
	// データ取得
	getInputs(gameConst)

	// 初期値設定処理　ここまで
	solver := NewSolver(TIME_LIMIT)
	pattern := 1
	if gameConst.MaxTurn < 11500 {
		pattern = 3
	}

	var actions []*Action
	score := 0
	if pattern == 1 {
		actions, score = solver.Solve(gameConst)
	} else if pattern == 3 {
		actions, score = solver.Solve3(gameConst)
	}

	// アクションを出力
	linev := [BOARD_WIDTH][BOARD_WIDTH - 1]int{}
	for i := range linev {
		for j := range linev[i] {
			linev[i][j] = 1
		}
	}
	lineh := [BOARD_WIDTH - 1][BOARD_WIDTH]int{}
	for i := range lineh {
		for j := range lineh[i] {
			lineh[i][j] = 1
		}
	}
	if pattern == 1 {
		for i := 0; i < BOARD_WIDTH-1; i++ {
			lineh[i][0] = 0
		}
		for k := range coords[gameConst.NumBaseTubes] {
			for index := range coords[gameConst.NumBaseTubes][k] {
				if index == 0 {
					continue
				}
				if index == DEFAULT_CELL_PER_GROUP {
					continue
				}
				pos := coords[gameConst.NumBaseTubes][k][index-1]
				pos2 := coords[gameConst.NumBaseTubes][k][index]
				vh, i, j := calcVH(pos, pos2)
				if vh == 0 {
					linev[i][j] = 0
				} else {
					lineh[i][j] = 0
				}
			}
		}
	}

	if pattern == 3 {
		for i := range snake {
			if i == 4 {
				break
			}
			ni := i + 1
			pos := snake[i]
			pos2 := snake[ni]
			vh, i, j := calcVH(pos, pos2)
			if vh == 0 {
				linev[i][j] = 0
			} else {
				lineh[i][j] = 0
			}
		}
	}

	for i := 0; i < BOARD_WIDTH; i++ {
		for j := 0; j < BOARD_WIDTH-1; j++ {
			fmt.Printf("%d", linev[i][j])
			if j < BOARD_WIDTH-2 {
				fmt.Printf(" ")
			} else {
				fmt.Println("")
			}
		}
	}
	for i := 0; i < BOARD_WIDTH-1; i++ {
		for j := 0; j < BOARD_WIDTH; j++ {
			fmt.Printf("%d", lineh[i][j])
			if j < BOARD_WIDTH-1 {
				fmt.Printf(" ")
			} else {
				fmt.Println("")

			}
		}
	}
	if !LOCAL_TEST || (!SUCCESSIVE && PRINT_ACTION) {
		for i := range actions {
			printAction(actions[i], gameConst, false)
		}
	}

	result.score = score

	return result
}

type Palette struct {
	main       *Will
	sub        []*Will
	sumError   float64
	sumProc1   int
	progress   int
	sumDiscard float64

	turn int
}

func NewPalette(gameConst *GameConst) *Palette {
	p := Palette{}
	p.main = NewWill()
	p.sub = make([]*Will, 0, gameConst.NumBaseTubes)
	for i := 0; i < gameConst.NumBaseTubes; i++ {
		p.sub = append(p.sub, NewWill())
	}
	return &p
}

func (p *Palette) Copy(gameConst *GameConst) *Palette {
	newp := NewPalette(gameConst)
	newp.Load(p)
	return newp
}

func (p *Palette) Load(p2 *Palette) {
	p.main.Load(p2.main)
	for i := range p.sub {
		p.sub[i].Load(p2.sub[i])
	}
	p.sumError = p2.sumError
	p.sumProc1 = p2.sumProc1
	p.progress = p2.progress
	p.sumDiscard = p2.sumDiscard

	p.turn = p2.turn
}
func (p *Palette) Init() {
	p.main.amount = 0
	p.main.size = BOARD_WIDTH * BOARD_WIDTH
	for i := range p.sub {
		p.sub[i].amount = 0
		p.sub[i].size = DEFAULT_CELL_PER_GROUP
		p.main.size -= DEFAULT_CELL_PER_GROUP
	}
	p.sumError = 0
	p.sumProc1 = 0
	p.progress = 0
	p.turn = 0
}

func (p *Palette) SetReasonableSize() {
	for i := range p.sub {
		if p.sub[i].size < DEFAULT_CELL_PER_GROUP {
			// 小さすぎるので修正
			sizediff := DEFAULT_CELL_PER_GROUP - p.sub[i].size
			p.sub[i].Expand(p.main, sizediff)
		}
	}
}

func (p *Palette) AddInk(gameConst *GameConst, subIndex int, tubeIndex int) {
	prop := p.sub[subIndex].amount / (1 + p.sub[subIndex].amount)
	newc := mix(p.sub[subIndex].CMY, gameConst.TubeCMYs[tubeIndex], prop)
	p.sub[subIndex].CMY = newc
	p.sub[subIndex].amount += 1
	p.sumProc1++
}

func (p *Palette) Deliver(gameConst *GameConst, usepanic bool) {
	if usepanic {
		// fmt.Fprintln(os.Stderr, "DEBUG:", p.progress, "(", p.main.amount, ")")
		// for i := range p.sub {
		// 	fmt.Fprintln(os.Stderr, p.sub[i])
		// }
		if p.main.amount < 1-EPSILON {
			fmt.Fprintln(os.Stderr, "ERROR: main.amount < 1-EPSILON", "(", p.main.amount, ")", "phase:", p.progress)
			fmt.Fprintln(os.Stderr, gameConst.NumTubes, gameConst.MaxTurn, gameConst.TubeCost)
			fmt.Fprintln(os.Stderr, "main:", p.main)
			for i := range p.sub {
				fmt.Fprintln(os.Stderr, "sub :", p.sub[i])
			}
			panic("")
		}
	}
	// if p.main.amount < 1 {
	// 	fmt.Fprintln(os.Stderr, "WARN: 1- EPSILON < main.amount < 1")
	// }
	diff := calcDiff(p.main.CMY, gameConst.RequestedCMYs[p.progress])
	p.sumError += diff
	p.main.Discard()
	p.progress += 1
}

func (p *Palette) ClearMain(gameConst *GameConst) {
	p.sumDiscard += p.main.amount
	p.main.Discard()
}

func (p *Palette) Blend(gameConst *GameConst, recipe *Recipe) {
	// keepが発生していないならexpand
	for subIndex := range recipe.recipe {
		if recipe.recipe[subIndex][2] == 0 && recipe.recipe[subIndex][0] != 0 {
			p.sub[subIndex].Expand(p.main, recipe.recipe[subIndex][0])
		}
	}
	for i := range recipe.add {
		if recipe.add[i] > 0 {
			p.AddInk(gameConst, i, gameConst.BaseTubes[i])
		}
	}
	// keepが発生するならkeep
	for subIndex := range recipe.recipe {
		if recipe.recipe[subIndex][2] != 0 {
			p.sub[subIndex].Keep(recipe.recipe[subIndex][2])
		}
	}
	// keepが発生してる場合はここでexpand
	for subIndex := range recipe.recipe {
		if recipe.recipe[subIndex][2] != 0 && recipe.recipe[subIndex][0] != 0 {
			p.sub[subIndex].Expand(p.main, recipe.recipe[subIndex][0])
		}
	}
	for subIndex := range recipe.recipe {
		if recipe.recipe[subIndex][1] != 0 {
			p.sub[subIndex].Shrink(p.main, recipe.recipe[subIndex][1])
		}
	}
	// release keep
	for subIndex := range recipe.recipe {
		if recipe.recipe[subIndex][2] != 0 {
			p.sub[subIndex].ReleaseKeep()
		}
	}
}

func (p *Palette) CalcScore(gameConst *GameConst) float64 {
	return 1 + p.sumError*10000 + float64(gameConst.TubeCost*(p.sumProc1-NUM_REQUESTED))
}

func mix(c1 [3]float64, c2 [3]float64, prop float64) [3]float64 {
	newc := [3]float64{}
	for j := range newc {
		newc[j] = c1[j]*prop + c2[j]*(1-prop)
	}
	return newc
}
func calcDiff(c1 [3]float64, c2 [3]float64) float64 {
	sqdiff := 0.0
	for i := 0; i < 3; i++ {
		d := (c1[i] - c2[i]) * (c1[i] - c2[i])
		sqdiff += d
	}
	return math.Sqrt(sqdiff)
}

type Will struct {
	CMY        [3]float64
	amount     float64
	size       int
	keepAmount float64
	keepSize   int
	keepCMY    [3]float64
}

func NewWill() *Will {
	w := Will{}
	return &w
}

func (w *Will) Copy() {
	neww := NewWill()
	neww.Load(w)
}

func (w *Will) Load(w2 *Will) {
	w.CMY = w2.CMY
	w.amount = w2.amount
	w.size = w2.size
	w.keepAmount = w2.keepAmount
	w.keepSize = w2.keepSize
	w.keepCMY = w2.keepCMY
}

func (w *Will) Keep(size int) {
	if w.size > 0 {
		amount := float64(size) / float64(w.size) * w.amount
		// fmt.Fprintln(os.Stderr, "keep", amount)
		w.keepAmount = amount
		w.keepSize = size
		w.keepCMY = w.CMY
		w.amount -= amount
		w.size -= size
	}
}
func (w *Will) ReleaseKeep() {
	// fmt.Fprintln(os.Stderr, "release", w.keepAmount)
	newc := mix(w.CMY, w.keepCMY, w.amount/(w.amount+w.keepAmount))
	w.amount += w.keepAmount
	w.CMY = newc

	w.size += w.keepSize
	w.keepAmount = 0
	w.keepSize = 0
}

func (w *Will) Expand(main *Will, sizediff int) {
	if main.amount > 0 && main.size > 0 {
		amount := main.amount * float64(sizediff) / float64(main.size) // mainから流入する量
		prop := w.amount / (amount + w.amount)
		// sub側は色更新が必要
		newc := mix(w.CMY, main.CMY, prop)
		w.amount += amount
		main.amount -= amount
		if main.amount < EPSILON && main.size == sizediff {
			main.amount = 0
		}
		w.CMY = newc
	}
	w.size += sizediff
	main.size -= sizediff
}

func (w *Will) Shrink(main *Will, sizediff int) {
	main.Expand(w, sizediff)
}

func (w *Will) Discard() {
	w.amount -= 1
	if w.amount < 0 {
		w.amount = 0
	}
}

type Recipe struct {
	recipe [][4]int
	add    []int
}

func NewRecipe(numGroup int) *Recipe {
	r := Recipe{}
	r.recipe = make([][4]int, numGroup)
	r.add = make([]int, numGroup)
	return &r
}

func (r *Recipe) Copy(numGroup int) *Recipe {
	newr := NewRecipe(numGroup)
	newr.Load(r)
	return newr
}

func (r *Recipe) Load(r2 *Recipe) {
	for i := range r.recipe {
		r.recipe[i] = r2.recipe[i]
	}
	for i := range r.add {
		r.add[i] = r2.add[i]
	}
}

// SolveWeights は 4 つの三次元ベクトル v1～v4、および目標ベクトル t
// （いずれも [3]float64）を受け取り、
//
//	a*v1 + b*v2 + c*v3 + d*v4 = t かつ a+b+c+d = 1
//
// を満たす重み [4]float64 を返します。
// 線形方程式を 3×3 系に帰着し、部分選択ピボット付きガウス消去により解きます。
// 結果の丸め誤差を抑えるため、最終的に絶対値が eps 未満の成分を 0 に丸めます。
func SolveWeights(
	v1, v2, v3, v4, t [3]float64,
) [4]float64 {
	const eps = 1e-12

	// 差分ベクトルを計算: u1 = v1 - v4, u2 = v2 - v4, u3 = v3 - v4
	var u [3][3]float64
	for i := 0; i < 3; i++ {
		u[0][i] = v1[i] - v4[i]
		u[1][i] = v2[i] - v4[i]
		u[2][i] = v3[i] - v4[i]
	}
	// 右辺: rhs = t - v4
	var rhs [3]float64
	for i := 0; i < 3; i++ {
		rhs[i] = t[i] - v4[i]
	}

	// 3×4 の拡大係数行列 mat を作成 (3行3列 + RHS)
	var mat [3][4]float64
	for i := 0; i < 3; i++ {
		mat[i][0] = u[0][i]
		mat[i][1] = u[1][i]
		mat[i][2] = u[2][i]
		mat[i][3] = rhs[i]
	}

	// 部分選択ピボット付きガウス消去 (3×3)
	for k := 0; k < 3; k++ {
		// pivot: k列目の絶対値が最大の行を選択
		pivot := k
		maxVal := math.Abs(mat[k][k])
		for i := k + 1; i < 3; i++ {
			if v := math.Abs(mat[i][k]); v > maxVal {
				maxVal = v
				pivot = i
			}
		}
		// 行交換
		if pivot != k {
			mat[k], mat[pivot] = mat[pivot], mat[k]
		}
		// pivot 要素が小さすぎたら eps を代入して分母ゼロを回避
		if math.Abs(mat[k][k]) < eps {
			mat[k][k] = eps
		}
		// 下行の消去
		for i := k + 1; i < 3; i++ {
			factor := mat[i][k] / mat[k][k]
			for j := k; j < 4; j++ {
				mat[i][j] -= factor * mat[k][j]
			}
		}
	}

	// 後退代入して x[0], x[1], x[2] を得る
	var x [3]float64
	for i := 2; i >= 0; i-- {
		sum := mat[i][3]
		for j := i + 1; j < 3; j++ {
			sum -= mat[i][j] * x[j]
		}
		diag := mat[i][i]
		if math.Abs(diag) < eps {
			diag = eps
		}
		x[i] = sum / diag
	}

	// a = x[0], b = x[1], c = x[2], そして d = 1 - a - b - c
	a, b, c := x[0], x[1], x[2]
	d := 1.0 - a - b - c

	sol := [4]float64{a, b, c, d}
	// 丸め: 絶対値が eps 未満の成分を 0 に
	for i := 0; i < 4; i++ {
		if math.Abs(sol[i]) < eps {
			sol[i] = 0
		}
	}
	return sol
}

func bruteforce(palette *Palette, goal [3]float64, gameConst *GameConst) *Recipe {
	bestValue := float64(INF)
	bestRecipe := NewRecipe(gameConst.NumBaseTubes)
	// mainに残留物があるなら釣り合いをとる
	// estimatedSize := BOARD_WIDTH + 0.5*float64(palette.main.size-BOARD_WIDTH)*4/float64(gameConst.NumBaseTubes) + float64(palette.main.size-BOARD_WIDTH)*float64(gameConst.NumBaseTubes-4)/float64(gameConst.NumBaseTubes)
	estimatedSize := float64(palette.main.size)
	// if palette.main.amount > 0 {
	// 	goal = mix(goal, palette.main.CMY, (1+palette.main.amount*estimatedSize/float64(palette.main.size))/(1))
	// }

	for i := 0; i < gameConst.NumBaseTubes; i++ {
		c1 := gameConst.TubeCMYs[gameConst.BaseTubes[i]]
		for j := i + 1; j < gameConst.NumBaseTubes; j++ {
			c2 := gameConst.TubeCMYs[gameConst.BaseTubes[j]]
			for k := j + 1; k < gameConst.NumBaseTubes; k++ {
				c3 := gameConst.TubeCMYs[gameConst.BaseTubes[k]]
				for l := k + 1; l < gameConst.NumBaseTubes; l++ {
					c4 := gameConst.TubeCMYs[gameConst.BaseTubes[l]]
					mainparam := SolveWeights(c1, c2, c3, c4, palette.main.CMY)
					param := SolveWeights(c1, c2, c3, c4, goal)
					nparam, ok := adjustWeights(param, false)
					if gameConst.useAll {
						if ok {
							for i := range param {
								param[i] = param[i]*(1+palette.main.amount*estimatedSize/float64(palette.main.size)) - mainparam[i]*palette.main.amount*estimatedSize/float64(palette.main.size)
							}
							nparam, _ = adjustWeights(param, true)
						} else {
							for i := range param {
								param[i] = param[i]*(1+estimatedSize/float64(palette.main.size)) - mainparam[i]*estimatedSize/float64(palette.main.size)
							}
							nparam, ok = adjustWeights(param, false)
							if ok {
								nparam, _ = adjustWeights(param, true)
							}
						}
					}
					if !ok {
						continue
					}
					maxmode := 1
					if gameConst.MaxTurn < 20000 {
						maxmode = 2
					}
					for mode2 := 0; mode2 < maxmode; mode2++ {
						nnparam := nparam
						if mode2 == 0 {
							needprop := 1.0 - palette.main.amount*BOARD_WIDTH/float64(palette.main.size)
							for i := range nparam {
								nnparam[i] *= needprop
							}
						} else {
							needprop := 1.0 - palette.main.amount
							for i := range nparam {
								nnparam[i] *= needprop
							}
						}

						kinds := [4]int{i, j, k, l}
						value, recipe := bruteforceMode(palette, kinds, nnparam, gameConst, 16, -1, 0, 0, nil, nil, nil, nil, nil)
						if value < bestValue {
							bestValue = value
							bestRecipe = recipe
						}
					}
				}
			}
		}
	}
	return bestRecipe
}

func bruteforceMode(palette *Palette, kinds [4]int, param [4]float64, gameConst *GameConst, maxmode int, additionalKind int, additinalnumer int, phase int, estimateCap []int, addCount []int, paramreservations [][4]float64, reservations [][4]int, remainedNeededAmounts []float64) (float64, *Recipe) {
	bestValue := float64(INF)
	bestRecipe := NewRecipe(gameConst.NumBaseTubes)
	// fmt.Fprintln(os.Stderr, "DEBUG:", param)
	for mode := 0; mode < maxmode; mode++ {
		recipe := getNearestRecipe(palette, kinds, param, gameConst, mode, phase)
		if additionalKind != -1 {
			recipe.recipe[additionalKind][1] = additinalnumer
		}
		if paramreservations != nil {
			for i := range estimateCap {
				if estimateCap[i] == addCount[i] {
					// もう加えられない
					if recipe.add[i] == 1 {
						// 代替を考える必要あり。次の要求のメイン部分で補填
						scheduledAmount := getAmountFromRecipe(palette.sub[i].amount, palette.sub[i].size, recipe.add[i], recipe.recipe[i])
						neededAmount := scheduledAmount - palette.sub[i].amount

						maxKind := -1
						maxValue := -100.0
						for j := range paramreservations[1] {
							kind := reservations[1][j]

							v := float64(estimateCap[kind]-addCount[kind]) + palette.sub[kind].amount - remainedNeededAmounts[kind] + float64(paramreservations[1][j])*0.2
							v += gameConst.Random.Float64() * 0.4
							if v > maxValue {
								maxValue = v
								maxKind = kind
							}
						}
						for kind := range estimateCap {

							v := float64(estimateCap[kind]-addCount[kind]) + palette.sub[kind].amount - remainedNeededAmounts[kind]
							v += gameConst.Random.Float64() * 0.4
							if v > maxValue {
								maxKind = kind
							}
						}
						newAmount := getAmountFromRecipe(palette.sub[maxKind].amount, palette.sub[maxKind].size, recipe.add[maxKind], recipe.recipe[maxKind])
						newAmount += neededAmount + palette.main.amount*float64(gameConst.CellPerGroup-palette.sub[i].size)/float64(palette.main.size)
						if newAmount > 1-EPSILON {
							newAmount = 1 - EPSILON
						}
						recipe.add[i] = 0
						recipe.recipe[i][0] = 0
						recipe.recipe[i][1] = palette.sub[i].size
						recipe.recipe[i][2] = 0

						if newAmount > palette.sub[maxKind].amount {
							recipe.add[maxKind] = 1
						}
						var r [4]int
						if gameConst.MaxTurn > 24000 {
							r, _ = getNearestRecipeForWill(palette.sub[maxKind], newAmount, gameConst, 0, 1)
						} else {
							r, _ = getNearestRecipeForWill(palette.sub[maxKind], newAmount, gameConst, 0, 0)
						}
						recipe.recipe[maxKind] = r

					}
				}
			}
		}
		value := evaluateRecipe(palette, recipe, gameConst)
		if value < bestValue {
			bestValue = value
			bestRecipe = recipe
		}
		// fmt.Fprintln(os.Stderr, "DEBUG:", "value", recipe, value)
	}
	// fmt.Fprintln(os.Stderr, "DEBUG:", "bestValue", bestValue,bestRecipe)
	return bestValue, bestRecipe
}

func evaluateRecipe(palette *Palette, recipe *Recipe, gameConst *GameConst) float64 {
	color := [3]float64{}
	amount := 0.0
	sumadd := 0
	mainAmount := palette.main.amount
	for i := range recipe.recipe {
		if recipe.recipe[i][0] == 0 {
			// extendなし
			continue
		}
		p := float64(recipe.recipe[i][0]) / float64(palette.main.size)                                             // mainからの流入割合
		p *= 1 - float64(recipe.recipe[i][1])/float64(palette.sub[i].size+recipe.recipe[i][0]-recipe.recipe[i][2]) // 返ってこない割合
		mainAmount -= palette.main.amount * p
	}

	for i := range recipe.add {
		sumadd += recipe.add[i]
	}
	for i := range recipe.recipe {
		denom := palette.sub[i].size + recipe.recipe[i][0] - recipe.recipe[i][2]
		numer := recipe.recipe[i][1]
		if numer == 0 || denom == 0 {
			continue
		}
		if (palette.sub[i].amount + float64(recipe.add[i])) == 0 {
			continue
		}
		remainingprop := 1.0
		if palette.sub[i].size > 0 {
			remainingprop = float64(palette.sub[i].size-recipe.recipe[i][2]) / float64(palette.sub[i].size)
		}
		tubeColor := gameConst.TubeCMYs[gameConst.BaseTubes[i]]
		plusAmount := (palette.sub[i].amount + float64(recipe.add[i])) * remainingprop * float64(numer) / float64(denom)
		prop := amount / (amount + plusAmount)
		color = mix(color, tubeColor, prop)
		amount += plusAmount
	}
	if mainAmount > 0 {
		color = mix(color, palette.main.CMY, amount/(amount+mainAmount))
		amount += mainAmount
	}
	value := calcDiff(gameConst.RequestedCMYs[palette.progress], color) * 10000
	if amount < 1-EPSILON {
		value += 100000
	} else {
		if !gameConst.useAll {
			if palette.progress < 50 || palette.sumDiscard/float64(palette.progress)*1000 > 0.2 {
				value += float64(gameConst.TubeCost) * (amount - 1)
			}
		} else {
			value += 000 * (amount - 1)
		}
	}
	if palette.sumProc1+sumadd > NUM_REQUESTED {
		value += float64(gameConst.TubeCost) * float64(sumadd) * 1
	}
	remainingProgress := NUM_REQUESTED - palette.progress
	actionPerProgress := (gameConst.MaxTurn - 20 - palette.turn) / remainingProgress
	if gameConst.useAll {
		actionPerProgress = (gameConst.MaxTurn - 100 - palette.turn) / remainingProgress
	}
	numLoop := float64(actionPerProgress-13) / 2
	if gameConst.useAll {
		numLoop = float64(actionPerProgress-12) / 2
	}
	if numLoop < 4.8 {
		mult := 0.3
		if numLoop < 3.8 {
			mult = 0.5
		}
		if numLoop < 2.8 {
			mult = 1.0
		}
		if numLoop < 1.8 {
			mult = 1.5
		}
		if numLoop < 0.8 {
			mult = 2.5
		}
		if numLoop < 0 {
			mult = 7
		}
		if numLoop < -0.2 {
			mult = 10
		}
		t := 0
		for i := range recipe.recipe {
			if recipe.recipe[i][0] != 0 {
				t += 2
			}
			if recipe.recipe[i][1] != 0 {
				t += 2
			}
			if recipe.recipe[i][2] != 0 {
				t += 2
			}
			if recipe.recipe[i][0]+palette.sub[i].size-recipe.recipe[i][1]-recipe.recipe[i][2] == 0 {
				t -= 2
			}
		}
		value += float64(t) * mult
	}
	return value
}

func getNearestRecipe(palette *Palette, kinds [4]int, param [4]float64, gameConst *GameConst, mode int, phase int) *Recipe {
	recipe := NewRecipe(gameConst.NumBaseTubes)
	vs := [4]float64{}
	for i, kind := range kinds {
		start := palette.sub[kind].amount
		if start < param[i] {
			start += 1
			recipe.add[kind] = 1
		}
	}
	depths := [4]int{}
	for i, kind := range kinds {
		r, v := getNearestRecipeForWill(palette.sub[kind], param[i], gameConst, (mode>>i)&1, depths[i])
		recipe.recipe[kind] = r
		vs[i] = v
		depths[i]++
	}
	remainingProgress := NUM_REQUESTED - palette.progress
	actionPerProgress := (gameConst.MaxTurn - 20 - palette.turn) / remainingProgress
	if gameConst.useAll {
		if phase == 0 {
			actionPerProgress = (gameConst.MaxTurn - 100 - palette.turn) / remainingProgress
		}
	}
	numLoop := (actionPerProgress - 13) / 2
	if gameConst.useAll {
		numLoop = (actionPerProgress - 12) / 2
	}
	if numLoop > 8 {
		numLoop = 8
	}
	dists := [4]float64{}
	for i := range dists {
		dists[i] = calcDiff(gameConst.TubeCMYs[gameConst.BaseTubes[kinds[i]]], gameConst.RequestedCMYs[palette.progress])
	}
	phase2 := 0
	center := -1
	based := 0.0
	for l := 0; l < numLoop; l++ {
		maxI := 0
		maxDiff := 0.0
		if phase2 == 0 {
			for i := 0; i < 4; i++ {
				d := math.Abs(vs[i] - param[i])
				if maxDiff < d*dists[i] {
					maxI = i
					maxDiff = d * dists[i]
				}
			}
			if depths[maxI] > 2 {
				maxDiff = 0.0
				center = maxI
				phase2 = 1
			}
		}
		if phase2 == 1 {
			based = (vs[center] - param[center]) / math.Max(0.1, param[center])
			based = math.Max(based, 0)
			for i := 0; i < 4; i++ {
				d := math.Abs((vs[i] - param[i]) - based*param[i])
				if maxDiff < d*dists[i] {
					maxI = i
					maxDiff = d * dists[i]
				}
			}
			if depths[maxI] > 2 {
				break
			}
		}

		i := maxI
		kind := kinds[i]
		np := param[i] + based*param[i]
		if np > param[i]+float64(recipe.add[kind]) {
			np = param[i] + float64(recipe.add[kind])
		}
		if np < 0 {
			np = 0
		}
		r, v := getNearestRecipeForWill(palette.sub[kind], np, gameConst, (mode>>i)&1, depths[i])
		recipe.recipe[kind] = r
		vs[i] = v
		depths[i]++
	}
	for _, kind := range kinds {
		if recipe.recipe[kind][1] == 0 {
			recipe.add[kind] = 0
		}
	}

	return recipe
}
func getNearestRecipeForWill(will *Will, param float64, gameConst *GameConst, mode int, depth int) ([4]int, float64) {
	bestr := [4]int{}
	start := will.amount
	add := false
	if start < param {
		start += 1
		add = true
	}
	diff := 0.0
	bestv := 0.0
	if depth == 0 {

		mindenom := will.size
		maxdenom := gameConst.CellPerGroup
		if !add {
			maxdenom = mindenom
		} else {
			mindenom = maxInt(gameConst.CellPerGroup-5, mindenom)
		}
		numer, denom := getNearestFraction(start, param, mindenom, maxdenom, mode)
		bestr[0] = denom - will.size
		bestr[1] = numer
		bestv = float64(numer) / float64(maxInt(denom, 1)) * start
	} else if depth == 1 {
		mindenom := will.size
		maxdenom := gameConst.CellPerGroup
		if add {
			mindenom = maxInt(1, mindenom)
		}
		numer, denom := getNearestFraction(start, param, mindenom, maxdenom, mode)
		bestr[0] = denom - will.size
		bestr[1] = numer
		bestv = float64(numer) / float64(maxInt(denom, 1)) * start
	} else {
		// keepも活用
		minKeepSize := 0
		// 余り量までにしておく
		maxKeepSize := int(float64(will.size) - (param * float64(will.size) / start))
		maxKeepSize = minInt(maxKeepSize, will.size-1)
		maxKeepSize = maxInt(maxKeepSize, minKeepSize)
		bestdiff := float64(INF)
		for keepSize := minKeepSize; keepSize <= maxKeepSize; keepSize++ {
			r2 := [4]int{}
			keepAmount := 0.0
			if will.size > 0 {
				keepAmount = start * float64(keepSize) / float64(will.size)
			}
			start2 := start - keepAmount
			mindenom := will.size - keepSize
			maxdenom := gameConst.CellPerGroup - keepSize
			if add {
				mindenom = maxInt(1, mindenom)
			}
			numer, denom := getNearestFraction(start2, param, mindenom, maxdenom, mode)

			r2[0] = denom - (will.size - keepSize)
			r2[1] = numer
			r2[2] = keepSize

			diff = math.Abs(float64(numer)/float64(maxInt(denom, 1))*start2 - param)
			if diff < bestdiff {
				bestr = r2
				bestdiff = diff
				bestv = float64(numer) / float64(maxInt(denom, 1)) * start2
			}
		}
	}

	return bestr, bestv
}

func getNearestFraction(start float64, goal float64, mindenom, maxdenom int, mode int) (int, int) {
	if goal < EPSILON {
		return 0, mindenom
	}
	bestNumer := 0
	bestDenom := mindenom
	bestValue := 10000.0
	for denom := mindenom; denom < maxdenom+1; denom++ {
		numer := int(goal*float64(denom)/start-EPSILON) + 1
		if mode == 1 {
			numer = int(goal*float64(denom)/start + EPSILON)
		}
		if denom == 0 {
			numer = 0
		}
		value := abs(start*float64(numer)/float64(maxInt(denom, 1)) - goal)
		if value < bestValue {
			bestValue = value
			bestNumer = numer
			bestDenom = denom
		}
	}
	return bestNumer, bestDenom
}

func calcVH(pos [2]int, pos2 [2]int) (int, int, int) {
	vh := 0
	if pos[0] != pos2[0] {
		vh = 1
	} else {
		vh = 0
	}
	i := minInt(pos[0], pos2[0])
	j := minInt(pos[1], pos2[1])
	return vh, i, j
}

// Package hullsupport provides a function to find a minimal subset of “base points”
// whose convex hull still contains all given “sub points,” using a volume‐based
// greedy heuristic in 3D. It does not rely on any external libraries.
//
// Example usage:
//
//   base := []hullsupport.Vec3{
//       {X: 0, Y: 0, Z: 0},
//       {X: 1, Y: 0, Z: 0},
//       {X: 0, Y: 1, Z: 0},
//       {X: 0, Y: 0, Z: 1},
//       {X: 1, Y: 1, Z: 1},
//       // …など k 個のベース座標
//   }
//   subs := []hullsupport.Vec3{
//       {X: 0.2, Y: 0.1, Z: 0.1},
//       {X: 0.3, Y: 0.4, Z: 0.2},
//       // …など任意の数のサブ座標
//   }
//   tol := 1e-9
//   result := hullsupport.MinimalSupportIndices(base, subs, tol)
//   // result は「残すべき base のインデックス (0 始まり)」のスライス
//

// Vec3 は 3 次元ベクトルを表す型 (X,Y,Z float64)。
type Vec3 struct {
	X, Y, Z float64
}

// --------------------------------------------------------------------------------
// 内部的に使うベクトル演算
// --------------------------------------------------------------------------------

func add(a, b Vec3) Vec3 {
	return Vec3{a.X + b.X, a.Y + b.Y, a.Z + b.Z}
}
func sub(a, b Vec3) Vec3 {
	return Vec3{a.X - b.X, a.Y - b.Y, a.Z - b.Z}
}
func scale(a Vec3, s float64) Vec3 {
	return Vec3{a.X * s, a.Y * s, a.Z * s}
}
func dot(a, b Vec3) float64 {
	return a.X*b.X + a.Y*b.Y + a.Z*b.Z
}
func cross(a, b Vec3) Vec3 {
	return Vec3{
		a.Y*b.Z - a.Z*b.Y,
		a.Z*b.X - a.X*b.Z,
		a.X*b.Y - a.Y*b.X,
	}
}
func abs(a float64) float64 {
	if a < 0 {
		return -a
	}
	return a
}

// --------------------------------------------------------------------------------
// Face, FaceLocal の定義
// --------------------------------------------------------------------------------

// Face は、凸包の面を表し、3 つの頂点インデックス (グローバル index) と
// その面の法線ベクトル(normal) と定数項(d) を保持する。
// plane equation: normal·x + d = 0, with normal pointing outward.
type Face struct {
	A, B, C int     // グローバルインデックス
	Normal  Vec3    // 法線ベクトル (向きは外側)
	D       float64 // 平面方程式の定数項
}

// faceLocal は buildHullLocal 内で使う「ローカル点インデックス」を使った構造体。
// Normal, D はローカル座標 (渡された pts[] の座標) に基づく。
type faceLocal struct {
	A, B, C int     // ローカルインデックス (pts[...] の添え字)
	Normal  Vec3    // 法線ベクトル (向きは外側)
	D       float64 // 平面方程式の定数項
}

// --------------------------------------------------------------------------------
// buildHullLocal: 3D 凸包を作成するインクリメンタルアルゴリズム
// pts は「ローカル座標点」のスライス (長さ n)。
// tol は数値誤差を吸収するための小さな正の閾値。
// 返り値は faceLocal 型のスライスで、各面ごとに頂点 (ローカル idx) と plane equation を持つ。
// tol の例: 1e-9 など。
// --------------------------------------------------------------------------------

func buildHullLocal(pts []Vec3, tol float64) []faceLocal {
	n := len(pts)
	if n < 4 {
		// 3 点以下では 3D における体積を持つ凸包にならないため、
		// 無効なケース。空スライスを返す。
		return nil
	}

	// (1) 初期テトラを作るための 4 つの非共面点を探す
	// p0 を 0 固定とし、p1 は p0 と距離 > tol となるもの
	p0 := 0
	p1 := -1
	for i := 1; i < n; i++ {
		if abs(dot(sub(pts[i], pts[p0]), sub(pts[i], pts[p0]))) > tol {
			p1 = i
			break
		}
	}
	if p1 < 0 {
		return nil // すべての点が同一点または重なり → 不適
	}
	// p2 は p0,p1 と面積 > tol な点 (非共線)
	p2 := -1
	for i := 1; i < n; i++ {
		if i == p1 {
			continue
		}
		cp := cross(sub(pts[p1], pts[p0]), sub(pts[i], pts[p0]))
		if abs(dot(cp, cp)) > tol {
			p2 = i
			break
		}
	}
	if p2 < 0 {
		return nil // すべて共線上
	}
	// p3 は p0,p1,p2 と体積 > tol の点 (非共面)
	p3 := -1
	baseNormal := cross(sub(pts[p1], pts[p0]), sub(pts[p2], pts[p0]))
	for i := 1; i < n; i++ {
		if i == p1 || i == p2 {
			continue
		}
		vol := dot(baseNormal, sub(pts[i], pts[p0])) / 6.0
		if abs(vol) > tol {
			p3 = i
			break
		}
	}
	if p3 < 0 {
		return nil // すべて共面
	}

	// (2) 初期テトラの頂点インデックス集合と、初期内点 interiorPoint を求める
	initial := []int{p0, p1, p2, p3}
	interiorPoint := Vec3{0, 0, 0}
	for _, idx := range initial {
		interiorPoint = add(interiorPoint, pts[idx])
	}
	interiorPoint = scale(interiorPoint, 1.0/4.0)

	// (3) 初期テトラの 4 面を作成。面の向きは全て外向きになるように調整。
	faces := make([]faceLocal, 0, 4)
	// テトラの面インデックス (A,B,C) の組み合わせ
	quad := [][]int{
		{p0, p1, p2},
		{p0, p1, p3},
		{p1, p2, p3},
		{p2, p0, p3},
	}
	for _, tri := range quad {
		f := makeFaceLocal(tri[0], tri[1], tri[2], pts, interiorPoint)
		faces = append(faces, f)
	}

	// (4) 残りの点を順に追加して凸包を拡張
	for i := 0; i < n; i++ {
		// すでにテトラに含まれている初期 4 点ならスキップ
		if i == p0 || i == p1 || i == p2 || i == p3 {
			continue
		}
		P := pts[i]
		// 可視面をマーク
		visible := make([]bool, len(faces))
		numVisible := 0
		for fi, f := range faces {
			// plane eq: normal·X + D = 0
			if dot(f.Normal, P)+f.D > tol {
				visible[fi] = true
				numVisible++
			}
		}
		if numVisible == 0 {
			// どの面にも可視でない → すでに内部 or 面上 → 追加不要
			continue
		}
		// (a) 可視な面を一度全て除去する準備
		//     ただし、削除前に horizon 辺を探す必要がある
		// horizon 辺を検出するため、visible faces の directed edge を集める
		type edgeKey struct{ U, V int }
		directedCount := make(map[edgeKey]int)
		for fi, f := range faces {
			if !visible[fi] {
				continue
			}
			// 面 f の頂点順 (A->B), (B->C), (C->A)
			directedCount[edgeKey{f.A, f.B}]++
			directedCount[edgeKey{f.B, f.C}]++
			directedCount[edgeKey{f.C, f.A}]++
		}
		// (b) Horizon 辺: directed 辺のリストを再度走査し、
		//     reversed edge が見つからないものを horizon とする
		var horizonEdges []edgeKey
		for e := range directedCount {
			rev := edgeKey{e.V, e.U}
			if directedCount[rev] == 0 {
				// reversed edge がない → horizon 辺
				horizonEdges = append(horizonEdges, e)
			}
		}
		// (c) visible faces を削除して、残りの faces を newFaces に集める
		newFaces := make([]faceLocal, 0, len(faces)-numVisible+len(horizonEdges))
		for fi, f := range faces {
			if !visible[fi] {
				newFaces = append(newFaces, f)
			}
		}
		// (d) horizon 辺それぞれについて、「辺 (U->V) と新点 i」を頂点とする面を追加
		for _, e := range horizonEdges {
			u, v := e.U, e.V
			// まず順序 (u,v,i) で法線を計算し、
			// interiorPoint から見て法線が内側を向くなら（dot>0）、
			// 順序を反転して (v,u,i) とする
			f := makeFaceLocal(u, v, i, pts, interiorPoint)
			newFaces = append(newFaces, f)
		}
		// (e) 更新: faces = newFaces
		faces = newFaces
	}

	return faces
}

// makeFaceLocal は、pts[a], pts[b], pts[c] を頂点とする面を作り、
// 法線が interiorPoint を向かない (外向き) になるように a,b,c の順序を調整する。
// 戻り値の faceLocal には、正しい法線および D が設定されている。
// plane eq: Normal·X + D = 0 となる。
func makeFaceLocal(a, b, c int, pts []Vec3, interiorPoint Vec3) faceLocal {
	A := pts[a]
	B := pts[b]
	C := pts[c]
	// 法線 = cross(B-A, C-A)
	normal := cross(sub(B, A), sub(C, A))
	// D = - dot(normal, A)
	Dval := -dot(normal, A)
	// interiorPoint がどちら側にあるか: dot(normal, interiorPoint - A)
	if dot(normal, sub(interiorPoint, A)) > 0 {
		// normal が内向き → 反転させる（b<->c を swap）
		normal = Vec3{-normal.X, -normal.Y, -normal.Z}
		Dval = -Dval
		// a,b,c のうち bとc を入れ替えて向きを揃える
		return faceLocal{A: a, B: c, C: b, Normal: normal, D: Dval}
	}
	return faceLocal{A: a, B: b, C: c, Normal: normal, D: Dval}
}

// --------------------------------------------------------------------------------
// computeVolume: 肉厚のない凸多面体 (faceLocal の集合) の体積を求める
// faces: faceLocal のスライス。各面の法線と D はすでに面が外向きになるようにある前提。
// ただし体積を求めるには、いったん「凸多面体内の interiorPoint」を得る必要がある。
// ここでは faces の頂点を一意に集め、その平均 (centroid) を interiorPoint として使う。
// 各面 (A,B,C) と interiorPoint で構成される四面体の体積を足し合わせる。
// tol は不要だがサインチェックに使わないのでここでは省略。
// --------------------------------------------------------------------------------

func computeVolumeLocal(faces []faceLocal, pts []Vec3) float64 {
	if len(faces) == 0 {
		return 0.0
	}
	// (1) faces のすべての頂点インデックスを一意に集める
	unique := make(map[int]struct{})
	for _, f := range faces {
		unique[f.A] = struct{}{}
		unique[f.B] = struct{}{}
		unique[f.C] = struct{}{}
	}
	// (2) centroid を計算
	centroid := Vec3{0, 0, 0}
	count := 0
	for idx := range unique {
		centroid = add(centroid, pts[idx])
		count++
	}
	centroid = scale(centroid, 1.0/float64(count))

	// (3) 各 face について四面体体積を計算して合算
	total := 0.0
	for _, f := range faces {
		A := pts[f.A]
		B := pts[f.B]
		C := pts[f.C]
		// 四面体 (centroid, A, B, C) の signed volume = dot((A - centroid), cross((B - centroid),(C - centroid))) / 6
		vol := dot(sub(A, centroid), cross(sub(B, centroid), sub(C, centroid))) / 6.0
		total += abs(vol)
	}
	return total
}

// --------------------------------------------------------------------------------
// pointInHullLocal: faces (ローカル faceLocal の集合) と pts で表される点 (ローカル index ではなく 座標 Vec3 のスライス) が
// すべて凸包の内部にあるかを判定する。tol は許容誤差。
// plane eq: Normal·X + D <= tol なら内部 or 面上。
// faces[i].Normal, faces[i].D は、pts を使って外向きに作られている想定。
// --------------------------------------------------------------------------------

func pointInHullLocal(faces []faceLocal, pts []Vec3, tol float64) bool {
	for _, p := range pts {
		for _, f := range faces {
			if dot(f.Normal, p)+f.D > tol {
				return false
			}
		}
	}
	return true
}

// --------------------------------------------------------------------------------
// MinimalSupportIndices: メイン関数
// basePoints: []Vec3 (長さ k)
// subPoints: []Vec3 (任意の長さ)
// tol: 内包判定や凸包構築時の数値誤差吸収用 (例: 1e-9)
// 返り値: 「残すべき basePoints のインデックス (0 始まり)」を昇順ソートした []int
//
// 手順:
// 1) basePoints 全体で凸包を構築 (buildHullLocal)。その頂点インデックスを初期候補 S とする。
// 2) Greedy loop:
//     a) S 内のインデックスに対応する座標スライス ptsS を作り、buildHullLocal で faces を再構築。
//     b) その faces を元に体積 Vorig を computeVolumeLocal で取得。
//     c) S の各頂点 v を外した集合 Sminus について:
//          ptsMinus を作り buildHullLocal で facesMinus を取得し、Vminus を computeVolumeLocal で取得。
//          Δv = Vorig - Vminus を記録。facesMinus と v の組み合わせを候補リストに追加。
//     d) 候補リストを Δv の小さい順にソートし、先頭から「facesMinus 内包判定 (pointInHullLocal)」を行う。
//          内包判定が真なら v を S から削除し、Greedy loop を再開。
//          どれも削除できなければ終了。
// 3) 残った S をソートして返す。
// --------------------------------------------------------------------------------

func MinimalSupportIndices(basePoints []Vec3, subPoints []Vec3, tol float64) []int {
	k := len(basePoints)
	if k == 0 {
		return nil
	}

	// 1) 初期凸包: basePoints 全体で buildHullLocal
	fullFaces := buildHullLocal(basePoints, tol)
	// fullFaces に含まれる頂点インデックスを Smap に格納
	Smap := make(map[int]struct{})
	for _, f := range fullFaces {
		Smap[f.A] = struct{}{}
		Smap[f.B] = struct{}{}
		Smap[f.C] = struct{}{}
	}

	// 2) Greedy loop: もう外せる頂点がなくなるまで回す
	for {
		/*if len(Smap) <= 8 {
			break
		}*/
		// (a) 現在の Smap から座標を取り出し、ptsS を作成
		Sindices := make([]int, 0, len(Smap))
		for idx := range Smap {
			Sindices = append(Sindices, idx)
		}
		ptsS := make([]Vec3, len(Sindices))
		for i, idx := range Sindices {
			ptsS[i] = basePoints[idx]
		}
		// (b) ptsS で凸包を再構築
		facesS := buildHullLocal(ptsS, tol)
		// facesS の頂点はローカルインデックス。これをグローバルインデックスに直すため、
		// 新たな Face を作る。
		// しかし内包判定や体積計算はローカル座標 ptsS で行い、
		// グローバルの Smap から再作成するのは最終結果だけでよい。
		// したがって、ここでは facesS をローカルのまま使って、体積計算・内包判定に利用する。

		// (c) Vorig を計算
		Vorig := computeVolumeLocal(facesS, ptsS)

		// (d) Δv を貯める候補を作成
		type candidate struct {
			delta      float64
			origIdx    int         // グローバルのインデックス
			facesMinus []faceLocal // ptsMinus のローカル凸包 faces
			ptsMinus   []Vec3      // ptsMinus の座標 (ローカル)
		}
		cands := make([]candidate, 0, len(Sindices))

		// Sindices の各頂点を順に外して試す
		for _, vIdx := range Sindices {
			// SminusIndices: Sindices から vIdx を除く
			var minusIdxs []int
			for _, idx := range Sindices {
				if idx == vIdx {
					continue
				}
				minusIdxs = append(minusIdxs, idx)
			}
			// ptsMinus: minusIdxs に対応する座標
			if len(minusIdxs) < 4 {
				// 4 点未満なら 3D hull は体積を持たないのでスキップ
				continue
			}
			ptsMinus := make([]Vec3, len(minusIdxs))
			for i, gIdx := range minusIdxs {
				ptsMinus[i] = basePoints[gIdx]
			}
			// 凸包構築
			facesMinus := buildHullLocal(ptsMinus, tol)
			// 体積計算
			Vminus := computeVolumeLocal(facesMinus, ptsMinus)
			delta := Vorig - Vminus
			if delta < 0 && delta > -1e-12 {
				delta = 0
			}
			cands = append(cands, candidate{
				delta:      delta,
				origIdx:    vIdx,
				facesMinus: facesMinus,
				ptsMinus:   ptsMinus,
			})
		}

		// (e) 候補が空ならもう外せない
		if len(cands) == 0 {
			break
		}
		// (f) delta の昇順にソート
		sort.Slice(cands, func(i, j int) bool {
			return cands[i].delta < cands[j].delta
		})

		// (g) 小さい順に、facesMinus で subPoints が内包されるかチェック
		removed := false
		for _, cd := range cands {
			// facesMinus はローカルインデックスを前提としているが、
			// 内包判定 pointInHullLocal は「facesMinus の plane eq」と
			// 「ptsMinus」だけを使うので OK。
			// ここでは subPoints (全体座標) を ptsMinus のローカル座標系でそのまま判定するのではなく、
			// すべての subPoints が facesMinus を構成する凸多面体内にあるかを判定する必要がある。
			// ただし facesMinus.PlaneEq は ptsMinus 頂点座標系で作られているが、座標系そのものは
			// すべてグローバル空間における実際の (x,y,z) なので、直接 subPoints を渡してよい。
			// （ptsMinus は単に座標を並べ直しているだけで、シーン全体のワールド座標系を使っているため）
			if pointInHullLocal(cd.facesMinus, subPoints, tol) {
				// 削除成功
				delete(Smap, cd.origIdx)
				removed = true
				break
			}
		}
		if !removed {
			// どれを外しても subPoints が内包されない → 終了
			break
		}
		// removed == true なら、Smap が更新されたので再ループ
	}

	// 3) 最終的に残った Smap のインデックスをソートして返す
	result := make([]int, 0, len(Smap))
	for idx := range Smap {
		result = append(result, idx)
	}
	sort.Ints(result)
	return result
}

// augmentIndicesWithClusters takes:
// - points: a slice of k 3D vertices ([3]float64).
// - selected: a slice of indices into points that are initially chosen.
// - extra: a slice of 1000 additional 3D coordinates ([3]float64).
//
// It returns a new slice of indices (into points) that:
//  1. Includes the original selected indices (deduplicated and validated).
//  2. If len(cleaned) < min(k, 8), it computes cluster centers of the 1000 extra points
//     (using k-means with numToAdd = min(k,8) - len(cleaned) clusters), then for each
//     cluster centroid, finds the nearest vertex in points that was not already selected,
//     and appends its index to the selection. Stops once the total count = min(k, 8).
func augmentIndicesWithClusters(
	points [][3]float64,
	selected []int,
	extra [][3]float64, // exactly 1000 3D points
	maxNum int,
) []int {
	k := len(points)
	if k == 0 {
		return nil
	}

	// Determine target number of indices: min(k, 8)
	target := maxInt(maxNum, len(selected))
	if k < target {
		target = k
	}

	n := len(points)

	// Step 1: Clean and dedupe the input 'selected' slice
	selectedMask := make([]bool, n)
	cleaned := make([]int, 0, len(selected))
	for _, idx := range selected {
		if idx < 0 || idx >= n {
			continue // skip invalid indices
		}
		if !selectedMask[idx] {
			selectedMask[idx] = true
			cleaned = append(cleaned, idx)
		}
	}

	// If already have enough (or more), trim and return
	if len(cleaned) >= target {
		return cleaned[:target]
	}

	// Step 2: Determine how many more to add
	numToAdd := target - len(cleaned)
	// Edge case: if extra has fewer points than numToAdd (unlikely since extra is 1000), just return
	if len(extra) == 0 || numToAdd <= 0 {
		return cleaned
	}

	// Step 3: Run k-means clustering on 'extra' to get 'numToAdd' centroids
	centroids := kMeans(extra, numToAdd, 10)

	// Step 4: For each centroid, find the nearest point in 'points' that isn't already selected
	for _, cent := range centroids {
		bestIdx := -1
		bestDistSq := math.Inf(1)

		// Compute distance from centroid to each candidate vertex in 'points'
		for i := 0; i < n; i++ {
			if selectedMask[i] {
				continue
			}
			dx := points[i][0] - cent[0]
			dy := points[i][1] - cent[1]
			dz := points[i][2] - cent[2]
			distSq := dx*dx + dy*dy + dz*dz
			if distSq < bestDistSq {
				bestDistSq = distSq
				bestIdx = i
			}
		}

		if bestIdx == -1 {
			// No more unselected points remain
			break
		}

		selectedMask[bestIdx] = true
		cleaned = append(cleaned, bestIdx)
		if len(cleaned) >= target {
			break
		}
	}

	return cleaned
}

// kMeans performs a simple k-means clustering on 'data' (slice of [3]float64).
// - kClusters: number of clusters to form.
// - maxIter: maximum number of iterations for centroid refinement.
// Returns a slice of length kClusters, each being a [3]float64 centroid.
func kMeans(data [][3]float64, kClusters int, maxIter int) [][3]float64 {
	n := len(data)
	if n == 0 || kClusters <= 0 {
		return nil
	}
	if kClusters > n {
		kClusters = n
	}

	// Initialize centroids by picking points spaced evenly through 'data'
	centroids := make([][3]float64, kClusters)
	step := n / kClusters
	for i := 0; i < kClusters; i++ {
		centroids[i] = data[i*step]
	}

	// Temporary slices for assignments and new centroid sums/counts
	assign := make([]int, n)
	newSums := make([][3]float64, kClusters)
	counts := make([]int, kClusters)

	for iter := 0; iter < maxIter; iter++ {
		// Reset sums and counts
		for i := 0; i < kClusters; i++ {
			newSums[i] = [3]float64{0, 0, 0}
			counts[i] = 0
		}

		// Assignment step: assign each point to nearest centroid
		for i, pt := range data {
			bestCluster := 0
			bestDist := distSq3D(pt, centroids[0])
			for c := 1; c < kClusters; c++ {
				d := distSq3D(pt, centroids[c])
				if d < bestDist {
					bestDist = d
					bestCluster = c
				}
			}
			assign[i] = bestCluster
			newSums[bestCluster][0] += pt[0]
			newSums[bestCluster][1] += pt[1]
			newSums[bestCluster][2] += pt[2]
			counts[bestCluster]++
		}

		// Update centroids and check for convergence
		converged := true
		for c := 0; c < kClusters; c++ {
			if counts[c] == 0 {
				// This cluster lost all points; leave centroid unchanged
				continue
			}
			mean := [3]float64{
				newSums[c][0] / float64(counts[c]),
				newSums[c][1] / float64(counts[c]),
				newSums[c][2] / float64(counts[c]),
			}
			if !almostEqual3D(centroids[c], mean) {
				converged = false
			}
			centroids[c] = mean
		}
		if converged {
			break
		}
	}

	return centroids
}

// distSq3D returns the squared Euclidean distance between two 3D points.
func distSq3D(a, b [3]float64) float64 {
	dx := a[0] - b[0]
	dy := a[1] - b[1]
	dz := a[2] - b[2]
	return dx*dx + dy*dy + dz*dz
}

// almostEqual3D checks if two 3D points are nearly equal (within a tiny epsilon).
func almostEqual3D(a, b [3]float64) bool {
	const eps = 1e-9
	return math.Abs(a[0]-b[0]) < eps &&
		math.Abs(a[1]-b[1]) < eps &&
		math.Abs(a[2]-b[2]) < eps
}

// CMYSolver encapsulates the CMY blending optimization steps.
type CMYSolver struct {
	// Input data
	k       int
	baseCMY [][3]float64
	goalCMY [][3]float64

	// Configuration (formerly constants)
	N            int
	MaxRadius    int
	destroyRate  float64
	regretK      int
	maxLNSIter   int
	hillIter     int
	initialColor [3]float64
	// Precomputed simplified cost matrix
	C [][]float64
}

// NewSolver initializes a solver with default parameters and precomputes costs.
func NewCMYSolver(k int, baseCMY, goalCMY [][3]float64, initialColor [3]float64) *CMYSolver {
	s := &CMYSolver{
		k:            k,
		baseCMY:      baseCMY,
		goalCMY:      goalCMY,
		N:            len(goalCMY),
		MaxRadius:    250,
		destroyRate:  1,
		regretK:      2,
		maxLNSIter:   1,
		hillIter:     2000000,
		initialColor: initialColor,
	}
	s.C = s.buildCostMatrix()
	return s
}

// Solve performs: EDF initial, LNS, hill-climb, initial5+nextBases determination, final penalty.
// Returns: plan sequence, initial5 base indices, nextBases sequence, and final penalty.
func (s *CMYSolver) Solve() ([]int, []int, []int, float64) {
	// 1) EDF initial feasible plan
	plan := s.initPlanEDF()
	// 2) LNS with simplified cost
	plan = s.solveLNS(plan)
	// 3) Determine initial5 and nextBases for blending
	initial5, nextBases := s.determineBases(plan, nil)
	// 4) Hill-climb using formal penalty (start from initial5)
	// plan = s.hillClimbFormal(plan, initial5)
	// 5) Final precise penalty (incorporates initial5 blending)
	pen, _ := s.finalPenalty(plan, initial5)
	return plan, initial5, nextBases, pen
}

func (s *CMYSolver) Improve(plan []int, initial5 []int, nextBases []int) ([]int, []int, []int, float64) {
	// 4) Hill-climb using formal penalty (start from initial5)
	plan = s.hillClimbFormal(plan, initial5)
	// 3) Determine initial5 and nextBases for blending
	initial5, nextBases = s.determineBases(plan, initial5)
	// 5) Final precise penalty (incorporates initial5 blending)
	pen, _ := s.finalPenalty(plan, initial5)
	return plan, initial5, nextBases, pen
}

// blend mixes prev and base with weights 0.8 and 0.2.
func blend(prev, base [3]float64) [3]float64 {
	return [3]float64{0.8*prev[0] + 0.2*base[0], 0.8*prev[1] + 0.2*base[1], 0.8*prev[2] + 0.2*base[2]}
}

// distSq computes squared Euclidean distance.
func distSq(a, b [3]float64) float64 {
	dx, dy, dz := a[0]-b[0], a[1]-b[1], a[2]-b[2]
	return dx*dx + dy*dy + dz*dz
}

// buildCostMatrix precomputes simplified costs C[i][j] for i->j transitions.
func (s *CMYSolver) buildCostMatrix() [][]float64 {
	C := make([][]float64, s.N+1)
	for i := 0; i <= s.N; i++ {
		C[i] = make([]float64, s.N)
		for j := 0; j < s.N; j++ {
			best := math.Inf(1)
			if i == s.N {
				// from start (0,0,0) approximate by single base
				for b := 0; b < s.k; b++ {
					var c [3]float64
					if s.initialColor[0] != -1 {
						c = blend(s.initialColor, s.baseCMY[b])
					} else {
						c = blend([3]float64{0.5, 0.5, 0.5}, s.baseCMY[b])
					}
					d := math.Sqrt(distSq(c, s.goalCMY[j]))
					if d < best {
						best = d
					}
				}
			} else {
				prev := s.goalCMY[i]
				for b := 0; b < s.k; b++ {
					c := blend(prev, s.baseCMY[b])
					if d := math.Sqrt(distSq(c, s.goalCMY[j])); d < best {
						best = d
					}
				}
			}
			C[i][j] = best
		}
	}
	return C
}

// initPlanEDF constructs a feasible initial plan using EDF heuristic.
func (s *CMYSolver) initPlanEDF() []int {
	plan := make([]int, s.N)
	used := make([]bool, s.N)
	deadline := make([]int, s.N)
	for i := 0; i < s.N; i++ {
		d := i + s.MaxRadius
		if d >= s.N {
			d = s.N - 1
		}
		deadline[i] = d
	}
	for t := 0; t < s.N; t++ {
		best, minDL := -1, s.N
		for i := 0; i < s.N; i++ {
			if used[i] {
				continue
			}
			low, high := i-s.MaxRadius, i+s.MaxRadius
			if low < 0 {
				low = 0
			}
			if high >= s.N {
				high = s.N - 1
			}
			if low <= t && t <= high && deadline[i] < minDL {
				minDL = deadline[i]
				best = i
			}
		}
		used[best] = true
		plan[t] = best
	}
	return plan
}

// simplifiedCost calculates sum of C transitions for a given plan.
func (s *CMYSolver) simplifiedCost(plan []int) float64 {
	c, prev := 0.0, s.N
	for _, v := range plan {
		c += s.C[prev][v]
		prev = v
	}
	return c
}

// solveLNS runs LNS with regret-k repair using simplifiedCost.
// solveLNS は LNS において、破壊ステップを
// 「エッジコストが大きい箇所の頂点を優先的に除去」する
// コストバイアス破壊に置き換えています。
func (s *CMYSolver) solveLNS(plan []int) []int {
	rand.Seed(time.Now().UnixNano())
	best := append([]int(nil), plan...)
	bestC := s.simplifiedCost(plan)
	// fmt.Fprintf(os.Stderr, "startSimpleCost=%.3f\n", bestC)

	// ループ開始
	for it := 1; it <= s.maxLNSIter; it++ {
		// 1) 各エッジの簡易コストを計算
		edgeCosts := make([]struct {
			idx  int
			cost float64
		}, s.N)
		prev := s.N
		for i, v := range plan {
			edgeCosts[i] = struct {
				idx  int
				cost float64
			}{i, s.C[prev][v]}
			prev = v
		}
		// 2) コスト降順でソート
		sort.Slice(edgeCosts, func(i, j int) bool {
			return edgeCosts[i].cost > edgeCosts[j].cost
		})

		// 3) 上位 n 個のエッジ位置に対応する頂点を除去
		n := int(math.Round(s.destroyRate * float64(s.N)))
		removed := make([]int, 0, n)
		for i := 0; i < n; i++ {
			removed = append(removed, plan[edgeCosts[i].idx])
		}

		// 4) regret-k 挿入で修復
		newPlan := s.repairRegret(plan, removed)

		// 5) 簡易コスト評価
		c := s.simplifiedCost(newPlan)
		if c < bestC {
			bestC = c
			copy(best, newPlan)
			// fmt.Fprintf(os.Stderr, "LNS iter=%d improved=%.3f\n", it, bestC)
		}
		plan = newPlan

		//if it%500 == 0 {
		//	fmt.Fprintf(os.Stderr, "LNS iter=%d currentSimple=%.3f\n", it, bestC)
		//}
	}

	return best
}

// repairRegret performs regret-k insertion repair for destroyed plan.
func (s *CMYSolver) repairRegret(plan, removed []int) []int {
	inSet := make([]bool, s.N)
	for _, v := range plan {
		inSet[v] = true
	}
	for _, v := range removed {
		inSet[v] = false
	}
	res := make([]int, 0, len(plan)-len(removed))
	for _, v := range plan {
		if inSet[v] {
			res = append(res, v)
		}
	}
	get := func(a, b int) float64 {
		if b == s.N {
			return 0
		}
		return s.C[a][b]
	}
	for len(removed) > 0 {
		bestReg, bi, bp := -1.0, 0, 0
		for ri, v := range removed {
			d1, d2 := math.Inf(1), math.Inf(1)
			pos1 := 0
			for pos := 0; pos <= len(res); pos++ {
				prev, next := s.N, s.N
				if pos > 0 {
					prev = res[pos-1]
				}
				if pos < len(res) {
					next = res[pos]
				}
				d := get(prev, v) + get(v, next) - get(prev, next)
				if d < d1 {
					d2, d1, pos1 = d1, d, pos
				} else if d < d2 {
					d2 = d
				}
			}
			reg := d2 - d1
			if reg > bestReg {
				bestReg, bi, bp = reg, ri, pos1
			}
		}
		v := removed[bi]
		tmp := make([]int, len(res)+1)
		copy(tmp, res[:bp])
		tmp[bp] = v
		copy(tmp[bp+1:], res[bp:])
		res = tmp
		removed = append(removed[:bi], removed[bi+1:]...)
	}
	return res
}

// hillClimbFormal refines plan via 2-swap hill climb using finalPenalty.
func (s *CMYSolver) hillClimbFormal(plan []int, init5 []int) []int {
	rand.Seed(time.Now().UnixNano())
	best := append([]int(nil), plan...)
	bestC, bestHistory := s.finalPenalty(best, init5)
	// fmt.Fprintf(os.Stderr, "startFormalCost=%.3f\n", bestC)
	// 山登り
	for it := 0; it < s.hillIter; it++ {
		p := rand.Intn(s.N)
		q := rand.Intn(s.N - 1)
		if q >= p {
			q++
		}
		if int(float64(p+1)/333.4) != int(float64(q+1)/333.4) {
			continue
		}
		if distSq(s.goalCMY[plan[p]], s.goalCMY[plan[q]]) > 0.1*0.1 {
			continue
		}
		if distSq(s.goalCMY[plan[p]], bestHistory[p]) < distSq(s.goalCMY[plan[q]], bestHistory[p]) {
			continue
		}
		plan[p], plan[q] = plan[q], plan[p]
		c, history := s.finalPenalty(plan, init5)
		if c < bestC {
			bestC = c
			bestHistory = history
			copy(best, plan)
			// fmt.Fprintf(os.Stderr, "[hillFormal] iter=%d improved=%.3f\n", it, bestC)
		} else {
			plan[p], plan[q] = plan[q], plan[p]
		}
	}
	_ = bestC
	return best
}

// determineBases selects 5 bases for first mix and then one per step.
func (s *CMYSolver) determineBases(plan []int, in5 []int) ([]int, []int) {
	firstIdx := plan[0]
	// pick 5 that minimize distance when blended sequentially
	init5 := make([]int, 5)
	if in5 != nil {
		init5 = in5
	}
	prev := [3]float64{0, 0, 0}
	if in5 == nil {
		// compute distance from each base to the first goal color
		pairs := make([]struct {
			idx int
			d   float64
		}, s.k)
		for b := 0; b < s.k; b++ {
			pairs[b] = struct {
				idx int
				d   float64
			}{b, distSq(s.baseCMY[b], s.goalCMY[firstIdx])}
		}
		sort.Slice(pairs, func(i, j int) bool { return pairs[i].d < pairs[j].d })
		// select the 5 closest bases
		for i := 0; i < 5; i++ {
			if len(pairs) == 4 || i == 4 {
				init5[i] = pairs[0].idx
			} else {
				init5[i] = pairs[i].idx
			}
		}
	}
	// compute the actual starting color as the average of those 5
	for _, b := range init5 {
		prev[0] += s.baseCMY[b][0]
		prev[1] += s.baseCMY[b][1]
		prev[2] += s.baseCMY[b][2]
	}
	for k := 0; k < 3; k++ {
		prev[k] /= 5
	}
	// nextBases
	nextBases := make([]int, s.N)
	// 0th uses last of init5
	nextBases[0] = init5[4]
	for t := 1; t < s.N; t++ {
		j := plan[t]
		bestD, bestB := math.Inf(1), 0
		for b := 0; b < s.k; b++ {
			c := blend(prev, s.baseCMY[b])
			if d := distSq(c, s.goalCMY[j]); d < bestD {
				bestD, bestB = d, b
			}
		}
		nextBases[t] = bestB
		prev = blend(prev, s.baseCMY[bestB])
	}
	return init5, nextBases
}

// finalPenalty performs the actual chain, first mixing init5 equally (0.2 each), then sequential.
func (s *CMYSolver) finalPenalty(plan []int, init5 []int) (float64, [][3]float64) {
	pen := 0.0
	history := make([][3]float64, 0, len(plan))
	// initial mix: equal combine
	prev := [3]float64{0, 0, 0}
	for _, b := range init5 {
		prev[0] += s.baseCMY[b][0]
		prev[1] += s.baseCMY[b][1]
		prev[2] += s.baseCMY[b][2]
	}
	for i := 0; i < 3; i++ {
		prev[i] /= 5
	}
	history = append(history, prev)
	// fmt.Fprintln(os.Stderr, "------------------")
	// penalty for 1st goal
	pen += math.Sqrt(distSq(prev, s.goalCMY[plan[0]]))
	// fmt.Fprintln(os.Stderr, 0, pen)
	// rest chain
	for t := 1; t < s.N; t++ {
		j := plan[t]
		bestD := math.Inf(1)
		var bestC [3]float64
		for b := 0; b < s.k; b++ {
			c := blend(prev, s.baseCMY[b])
			if d := distSq(c, s.goalCMY[j]); d < bestD {
				bestD, bestC = d, c
			}
		}
		pen += math.Sqrt(bestD)
		prev = bestC
		history = append(history, prev)
		// fmt.Fprintln(os.Stderr, plan[t], math.Sqrt(bestD))
	}
	return pen, history
}

// Tが比較的小で使用
func (s *Solver) Solve3(gameConst *GameConst) ([]*Action, int) {
	start := time.Now()
	_ = start
	maxActions := make([]*Action, 0, gameConst.MaxTurn)
	maxScore := 0.0
	_ = maxScore

	// 貪欲を書くならここ
	score := 0
	plan := make([]int, 0)
	init5 := make([]int, 5)
	nextBases := make([]int, 0)
	pen := 0.0
	initialColor := [3]float64{}
	initialColor[0] = -1
	numLoop := 3
	for loop := 0; loop < numLoop; loop++ {
		cmySolver := NewCMYSolver(gameConst.NumTubes, gameConst.TubeCMYs, gameConst.RequestedCMYs[(NUM_REQUESTED*loop/numLoop):(NUM_REQUESTED*(loop+1)/numLoop)], initialColor)
		partplan, partinit5, partnextBases, partpen := cmySolver.Solve()
		for i := range partplan {
			partplan[i] += (NUM_REQUESTED * loop / numLoop)
		}
		plan = append(plan, partplan...)
		nextBases = append(nextBases, partnextBases...)
		if loop == 0 {
			init5 = partinit5
		}
		initialColor = gameConst.RequestedCMYs[partplan[len(partplan)-1]]
		pen += partpen
	}
	cmySolver := NewCMYSolver(gameConst.NumTubes, gameConst.TubeCMYs, gameConst.RequestedCMYs[:], [3]float64{-1, 0, 0})
	plan, init5, nextBases, pen = cmySolver.Improve(plan, init5, nextBases)
	// for _, v := range plan {
	// 	fmt.Fprintln(w, v)
	// }
	// fmt.Fprintln(w, init5)
	// fmt.Fprintln(w, nextBases)
	// fmt.Fprintf(w, "%.6f\n", pen)
	addPos := 0
	for i := range init5 {
		if i == 4 {
			continue
		}
		action := NewAction()
		action.actionType = 1
		action.pos = snake[addPos]
		action.tube = init5[i]
		addPos++
		maxActions = append(maxActions, action)
	}
	set := make([]int, NUM_REQUESTED)
	for i := range set {
		set[i] = -1
	}
	progress := 0
	planIndex := 0
	for progress < NUM_REQUESTED {
		if set[progress] >= 0 {
			i := set[progress]
			action := NewAction()
			action.actionType = 2
			action.pos = snake[i]
			maxActions = append(maxActions, action)
			progress++
			continue
		}
		index := plan[planIndex]
		keepPos := planIndex % (BOARD_WIDTH * BOARD_WIDTH)
		set[index] = keepPos
		if true {
			action := NewAction()
			action.actionType = 1
			action.pos = snake[addPos]
			action.tube = nextBases[planIndex]
			addPos++
			if addPos >= BOARD_WIDTH*BOARD_WIDTH {
				addPos -= BOARD_WIDTH * BOARD_WIDTH
			}
			maxActions = append(maxActions, action)
		}
		if true {
			action := NewAction()
			action.actionType = 4
			p1 := addPos - 5
			p2 := addPos - 4
			if p1 < 0 {
				p1 += BOARD_WIDTH * BOARD_WIDTH
			}
			if p2 < 0 {
				p2 += BOARD_WIDTH * BOARD_WIDTH
			}
			action.pos = snake[p1]
			action.pos2 = snake[p2]
			maxActions = append(maxActions, action)
		}
		if true {
			action := NewAction()
			action.actionType = 4
			p1 := addPos - 1
			p2 := addPos - 0
			if p1 < 0 {
				p1 += BOARD_WIDTH * BOARD_WIDTH
			}
			action.pos = snake[p1]
			action.pos2 = snake[p2]
			maxActions = append(maxActions, action)
		}
		planIndex++

	}
	score = 1 + int(pen*10000) + 4*(gameConst.TubeCost)

	if len(maxActions) > gameConst.MaxTurn {
		score = -1
	}
	fmt.Fprintln(os.Stderr, len(maxActions), gameConst.MaxTurn)

	return maxActions, score
}
